// Daily quota for API-key clients (see docs/QUOTA.md).
export function checkQuota(
  store: CounterStore,
  ctx: RequestContext,
  day: string,
): LimitVerdict {
  if (!ctx.apiKey) return { allowed: true, reason: "ok" };
  const key = `quota:${ctx.apiKey}:${day}`;
  const result = store.checkAndIncrement(key, 1000);
  return result.allowed ? { allowed: true, reason: "ok" } : { allowed: false, reason: "quota" };
